class Gradebook:
    def __init__(self) -> None:
        # Stores assignment metadata: name -> {"weight": float, "kind": str}
        self.assignments: dict[str, dict] = {}
        # Stores recorded grades: student -> {assignment_name: grade}
        self.grades: dict[str, dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments[name] = {"weight": float(weight), "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        grade = float(grade)
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the valid scale of 2.0 to 5.0.")

        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        if not self.assignments:
            return 0.0

        student_grades = self.grades.get(student, {})

        # Collect all assignments with their effective grades
        effective_items = []
        for name, info in self.assignments.items():
            # If an assignment has no recorded grade, it defaults to 2.0
            grade = student_grades.get(name, 2.0)
            effective_items.append({
                "name": name,
                "grade": grade,
                "weight": info["weight"],
                "kind": info["kind"],
            })

        # Check quiz drop rule: if more than one quiz, drop the lowest quiz grade
        quiz_items = [item for item in effective_items if item["kind"] == "quiz"]
        dropped_item = None
        if len(quiz_items) > 1:
            dropped_item = min(quiz_items, key=lambda x: x["grade"])

        # Compute weighted average
        total_weighted_score = 0.0
        total_weight = 0.0

        for item in effective_items:
            if item is dropped_item:
                continue
            total_weighted_score += item["grade"] * item["weight"]
            total_weight += item["weight"]

        if total_weight == 0.0:
            return 0.0

        return round(total_weighted_score / total_weight, 2)
```

